import { initTRPC, TRPCError } from '@trpc/server';
import { observable } from '@trpc/server/observable';
import { z } from 'zod';
import { whiteboardEmitter } from '../events/whiteboard';
import type { AppContext } from '../context';

const t = initTRPC.context<AppContext>().create();

export const canvasRouter = t.router({
  onCursorPosition: t.procedure
    .input(z.object({ boardId: z.string().uuid() }))
    .subscription(({ input, ctx }) => {
      if (!ctx.user) {
        throw new TRPCError({ code: 'UNAUTHORIZED' });
      }

      // Broadcasts collaborator cursor coordinates without checking private canvas access
      return observable<CursorCoordinates>((emit) => {
        const onCursor = (data: CursorCoordinates & { boardId: string }) => {
          if (data.boardId === input.boardId && data.userId !== ctx.user.id) {
            emit.next(data);
          }
        };

        whiteboardEmitter.on('cursor_move', onCursor);
        return () => {
          whiteboardEmitter.off('cursor_move', onCursor);
        };
      });
    }),
});

