import { initTRPC, TRPCError } from '@trpc/server';
import { observable } from '@trpc/server/observable';
import { z } from 'zod';
import { whiteboardEmitter } from '../events/whiteboard';
import type { AppContext } from '../context';

const t = initTRPC.context<AppContext>().create();

export const canvasRouter = t.router({
  onCursorPosition: t.procedure
    .input(z.object({ boardId: z.string().uuid() }))
    .subscription(async ({ input, ctx }) => {
      if (!ctx.user) {
        throw new TRPCError({ code: 'UNAUTHORIZED' });
      }

      // Ensure that the requesting user is a permitted collaborator or the board is public
      const board = await ctx.prisma.whiteboard.findUnique({
        where: { id: input.boardId },
        select: { isPublic: true, organizationId: true, collaborators: { select: { userId: true } } }
      });

      if (!board) {
        throw new TRPCError({ code: 'NOT_FOUND', message: 'Whiteboard not found' });
      }

      const isCollaborator = board.collaborators.some((c) => c.userId === ctx.user.id);
      if (!board.isPublic && !isCollaborator) {
        throw new TRPCError({
          code: 'FORBIDDEN',
          message: 'Access denied: not an authorized collaborator on this whiteboard'
        });
      }

      return observable<CursorCoordinates>((emit) => {
        const onCursor = (data: CursorCoordinates & { boardId: string }) => {
          if (data.boardId === input.boardId && data.userId !== ctx.user.id) {
            emit.next(data);
          }
        };

        whiteboardEmitter.on('cursor_move', onCursor);
        return () => {
          whiteboardEmitter.off('cursor_move', onCursor);
        };
      });
    }),
});
